package com.neocoffee.smsgateway;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.telephony.SmsManager;import android.telephony.SubscriptionInfo;import android.telephony.SubscriptionManager;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
 private static final int PERMISSIONS=40;private final Handler handler=new Handler(Looper.getMainLooper());private EditText url,token,testPhone;private Spinner simChoice;private TextView status,activity,fromDate,toDate,report;private SharedPreferences prefs;private final List<Integer>simIds=new ArrayList<>();private final List<String>simLabels=new ArrayList<>();private final Calendar from=Calendar.getInstance(),to=Calendar.getInstance();private final Runnable refresh=new Runnable(){public void run(){showState();handler.postDelayed(this,2000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_main);prefs=getSharedPreferences("gateway",MODE_PRIVATE);url=findViewById(R.id.siteUrl);token=findViewById(R.id.deviceToken);testPhone=findViewById(R.id.testPhone);simChoice=findViewById(R.id.simChoice);status=findViewById(R.id.status);activity=findViewById(R.id.lastActivity);fromDate=findViewById(R.id.fromDate);toDate=findViewById(R.id.toDate);report=findViewById(R.id.reportResult);String gatewayUrl=getIntent().getStringExtra("gateway_url"),gatewayToken=getIntent().getStringExtra("gateway_token");url.setText(gatewayUrl==null?prefs.getString("url",""):gatewayUrl);token.setText(gatewayToken==null?prefs.getString("token",""):gatewayToken);String test=getIntent().getStringExtra("test_phone");if(test!=null)testPhone.setText(test);from.set(Calendar.HOUR_OF_DAY,0);from.set(Calendar.MINUTE,0);from.set(Calendar.SECOND,0);to.set(Calendar.HOUR_OF_DAY,23);to.set(Calendar.MINUTE,59);to.set(Calendar.SECOND,59);updateDates();loadSims();if(getIntent().getBooleanExtra("confirm_test",false))MessageLog.confirmLatestTest(this);if(checkSelfPermission(Manifest.permission.READ_PHONE_STATE)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.READ_PHONE_STATE},PERMISSIONS);findViewById(R.id.saveStart).setOnClickListener(v->saveAndStart());findViewById(R.id.sendTest).setOnClickListener(v->sendTestSms());findViewById(R.id.confirmTest).setOnClickListener(v->{boolean done=MessageLog.confirmLatestTest(this);Toast.makeText(this,done?"تم تأكيد وصول آخر رسالة اختبار":"لا توجد رسالة اختبار",Toast.LENGTH_LONG).show();showReport();});findViewById(R.id.showReport).setOnClickListener(v->showReport());fromDate.setOnClickListener(v->pickDate(from));toDate.setOnClickListener(v->pickDate(to));findViewById(R.id.stop).setOnClickListener(v->{stopService(new Intent(this,GatewayService.class));prefs.edit().putBoolean("running",false).apply();showState();});showReport();}
 private void loadSims(){simIds.clear();simLabels.clear();if(checkSelfPermission(Manifest.permission.READ_PHONE_STATE)==PackageManager.PERMISSION_GRANTED){SubscriptionManager manager=getSystemService(SubscriptionManager.class);List<SubscriptionInfo>active=manager.getActiveSubscriptionInfoList();if(active!=null)for(SubscriptionInfo info:active){simIds.add(info.getSubscriptionId());CharSequence carrier=info.getCarrierName();simLabels.add("SIM "+(info.getSimSlotIndex()+1)+(carrier==null||carrier.length()==0?"":" — "+carrier));}}if(simLabels.isEmpty()){simIds.add(SubscriptionManager.getDefaultSmsSubscriptionId());simLabels.add("خط SMS الافتراضي في الهاتف");}simChoice.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,simLabels));simChoice.setContentDescription("الخطوط المتاحة: "+String.join("، ",simLabels));int saved=prefs.getInt("sub_id",SubscriptionManager.getDefaultSmsSubscriptionId());int selected=simIds.indexOf(saved);String preferred=getIntent().getStringExtra("preferred_carrier");if(preferred!=null)for(int i=0;i<simLabels.size();i++)if(simLabels.get(i).toLowerCase(Locale.ROOT).contains(preferred.toLowerCase(Locale.ROOT))){selected=i;prefs.edit().putInt("sub_id",simIds.get(i)).apply();break;}simChoice.setSelection(selected<0?0:selected);}
 private void saveAndStart(){String base=url.getText().toString().trim().replaceAll("/+$","");String key=token.getText().toString().trim();boolean secure=base.startsWith("https://"),local=base.matches("http://(127\\.0\\.0\\.1|localhost)(:\\d+)?");if((!secure&&!local)||key.length()<20){Toast.makeText(this,"أدخل رابط HTTPS ومفتاح جهاز طويل وصحيح",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("url",base).putString("token",key).apply();List<String>missing=new ArrayList<>();if(checkSelfPermission(Manifest.permission.SEND_SMS)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.SEND_SMS);if(checkSelfPermission(Manifest.permission.READ_PHONE_STATE)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.READ_PHONE_STATE);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)missing.add(Manifest.permission.POST_NOTIFICATIONS);if(!missing.isEmpty()){requestPermissions(missing.toArray(new String[0]),PERMISSIONS);return;}saveSimAndStart();}
 private void saveSimAndStart(){if(!simIds.isEmpty())prefs.edit().putInt("sub_id",simIds.get(simChoice.getSelectedItemPosition())).apply();startGateway();}
 private void sendTestSms(){String phone=testPhone.getText().toString().replaceAll("\\s+","");if(!phone.matches("(?:\\+?20|0)1[0125]\\d{8}")){Toast.makeText(this,"أدخل رقم موبايل مصري صحيح",Toast.LENGTH_LONG).show();return;}if(checkSelfPermission(Manifest.permission.SEND_SMS)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.SEND_SMS},PERMISSIONS);return;}if(simIds.isEmpty()){Toast.makeText(this,"لا يوجد خط نشط للإرسال",Toast.LENGTH_LONG).show();return;}int pos=simChoice.getSelectedItemPosition(),subId=simIds.get(pos);String sim=simLabels.get(pos);prefs.edit().putInt("sub_id",subId).apply();int request=(int)(System.currentTimeMillis()&0x7fffffff);Intent result=new Intent(this,SmsResultReceiver.class).putExtra("test",true).putExtra("phone",phone).putExtra("sim",sim);PendingIntent pi=PendingIntent.getBroadcast(this,request,result,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);SmsManager manager;if(Build.VERSION.SDK_INT>=31)manager=getSystemService(SmsManager.class).createForSubscriptionId(subId);else manager=SmsManager.getSmsManagerForSubscriptionId(subId);manager.sendTextMessage(phone,null,"Neo Coffee SMS Gateway test. The selected SIM is working.",pi,null);Toast.makeText(this,"تم تسليم رسالة الاختبار إلى نظام الإرسال",Toast.LENGTH_LONG).show();}
 private void pickDate(Calendar c){new DatePickerDialog(this,(v,y,m,d)->{c.set(y,m,d);if(c==from){c.set(Calendar.HOUR_OF_DAY,0);c.set(Calendar.MINUTE,0);c.set(Calendar.SECOND,0);}else{c.set(Calendar.HOUR_OF_DAY,23);c.set(Calendar.MINUTE,59);c.set(Calendar.SECOND,59);}updateDates();showReport();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show();}
 private void updateDates(){java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("dd/MM/yyyy",new Locale("ar"));fromDate.setText(f.format(from.getTime()));toDate.setText(f.format(to.getTime()));}
 private void showReport(){report.setText(MessageLog.report(this,from.getTimeInMillis(),to.getTimeInMillis()));}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r!=PERMISSIONS)return;if(checkSelfPermission(Manifest.permission.READ_PHONE_STATE)==PackageManager.PERMISSION_GRANTED)loadSims();if(checkSelfPermission(Manifest.permission.SEND_SMS)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.READ_PHONE_STATE)==PackageManager.PERMISSION_GRANTED&&prefs.contains("url")&&prefs.contains("token"))saveSimAndStart();else if(checkSelfPermission(Manifest.permission.READ_PHONE_STATE)!=PackageManager.PERMISSION_GRANTED)Toast.makeText(this,"صلاحية الهاتف مطلوبة لعرض SIM 1 وSIM 2",Toast.LENGTH_LONG).show();}
 private void startGateway(){startForegroundService(new Intent(this,GatewayService.class));prefs.edit().putBoolean("running",true).apply();showState();}private void showState(){status.setText(prefs.getBoolean("running",false)?"تعمل الآن":"متوقفة");activity.setText(prefs.getString("last","لا يوجد نشاط حتى الآن"));}
 @Override protected void onResume(){super.onResume();handler.post(refresh);if(prefs.getBoolean("running",false)&&prefs.contains("url")&&prefs.contains("token")&&checkSelfPermission(Manifest.permission.SEND_SMS)==PackageManager.PERMISSION_GRANTED&&checkSelfPermission(Manifest.permission.READ_PHONE_STATE)==PackageManager.PERMISSION_GRANTED)startGateway();}@Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
}
